// function sumPositive(arr) mein array do
// Agar array nahi ya empty: 0
// Agar koi non-number hai: "Invalid element"
// Warna sirf positive numbers ka sum do

solution:
function sumPositive(arr) {
  if (!Array.isArray(arr) || arr.length === 0) return 0
  if (arr.some(item => typeof item !== "number")) return "Invalid element"
  return arr.filter(n => n > 0).reduce((acc, n) => acc + n, 0)
}
